package api

import (
	"context"
	"crypto/rand"
	"embed"
	"encoding/base64"
	"html"
	"io/fs"
	"net/http"
	"net/url"
	"path"
	"strings"
	"time"

	"github.com/yernsun/network-service-composer/internal/i18n"
)

// Frontend assets are generated by make frontend-build before Go compilation.
//
//go:embed all:frontend-dist
var frontendFiles embed.FS

func (s *Server) spaPage(w http.ResponseWriter, r *http.Request) {
	if !knownSPAPath(r.URL.Path) {
		http.NotFound(w, r)
		return
	}
	body, err := frontendFiles.ReadFile("frontend-dist/index.html")
	if err != nil {
		s.writeProblem(w, r, 503, "system.not_ready", nil, "")
		return
	}
	nonceBytes := make([]byte, 24)
	// crypto/rand.Read fills the buffer or terminates on entropy failure.
	rand.Read(nonceBytes)
	nonce := base64.RawStdEncoding.EncodeToString(nonceBytes)
	w.Header().Set("Content-Security-Policy", "default-src 'self'; img-src 'self' data:; style-src 'self' 'nonce-"+nonce+"'; style-src-attr 'unsafe-inline'; script-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	page := strings.ReplaceAll(string(body), "__NSC_CSP_NONCE__", nonce)
	page = strings.ReplaceAll(page, "__NSC_LOCALE__", html.EscapeString(string(requestedLocale(r))))
	_, _ = w.Write([]byte(page))
}

func knownSPAPath(value string) bool {
	if value == "/login" || value == "/logout" {
		return true
	}
	if value == "" || !strings.HasPrefix(value, "/") || path.Clean(value) != value || strings.Contains(value, "\\") {
		return false
	}
	parts := strings.Split(strings.TrimPrefix(value, "/"), "/")
	switch parts[0] {
	case "account", "users":
		return len(parts) == 1
	case "projects":
		if len(parts) == 1 {
			return true
		}
		if parts[1] == "applications" {
			return len(parts) <= 3
		}
		if len(parts) == 2 || (len(parts) == 3 && parts[2] == "variables") {
			return true
		}
		if parts[2] != "environments" {
			return false
		}
		if len(parts) == 3 || len(parts) == 4 {
			return true
		}
		if len(parts) == 5 {
			switch parts[4] {
			case "variables", "compose", "updates", "applications", "services", "domains", "routes", "certificates", "deployments", "overview", "configs", "gateways", "events", "workloadHistory":
				return true
			default:
				return false
			}
		}
		if len(parts) == 6 {
			switch parts[4] {
			case "applications", "services", "domains", "routes", "deployments":
				return true
			default:
				return false
			}
		}
		return len(parts) == 7 && ((parts[4] == "domains" && parts[6] == "nginx") || (parts[4] == "applications" && parts[6] == "compose"))
	case "services":
		if len(parts) <= 2 {
			return true
		}
		return len(parts) == 3 && (parts[1] == "routes" || parts[1] == "domains")
	case "infrastructure":
		if len(parts) == 1 || (len(parts) == 2 && (parts[1] == "nodes" || parts[1] == "events" || parts[1] == "ha")) {
			return true
		}
		if parts[1] == "gateway-pools" || parts[1] == "gateways" || parts[1] == "certificates" {
			return len(parts) <= 3
		}
		if parts[1] != "runtimes" {
			return false
		}
		if len(parts) <= 3 {
			return true
		}
		if len(parts) == 4 {
			return parts[3] == "nodes" || parts[3] == "containers" || parts[3] == "tasks" || parts[3] == "instances"
		}
		return len(parts) == 5 && (parts[3] == "nodes" || parts[3] == "tasks" || parts[3] == "containers" || parts[3] == "instances")
	case "operations":
		return len(parts) <= 2
	case "market":
		return len(parts) <= 2
	default:
		return false
	}
}

func (s *Server) frontendAsset(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimPrefix(r.URL.Path, "/assets/")
	if name == "" || strings.Contains(name, "\\") || path.Clean(name) != name {
		http.NotFound(w, r)
		return
	}
	assets, _ := fs.Sub(frontendFiles, "frontend-dist/assets")
	info, err := fs.Stat(assets, name)
	if err != nil || info.IsDir() {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
	http.StripPrefix("/assets/", http.FileServer(http.FS(assets))).ServeHTTP(w, r)
}

func requestActor(r *http.Request) string {
	if key, ok := requestOpenAPIKey(r); ok {
		return key.ID
	}
	user, ok := requestUser(r)
	if ok {
		return user.ID
	}
	return "unauthenticated"
}

func (s *Server) sessionAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		sess, ok := s.readSession(r)
		if !ok {
			s.writeProblem(w, r, 401, "auth.required", nil, "")
			return
		}
		if r.Method != "GET" && r.Method != "HEAD" && r.Method != "OPTIONS" {
			if !sameOrigin(r) || !secureEqual(r.Header.Get("X-CSRF-Token"), sess.CSRF) {
				s.writeProblem(w, r, 403, "csrf.invalid", nil, "")
				return
			}
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), sessionKey{}, sess)))
	})
}

// JSON-only login/locale plus same-origin checks prevent cross-site form submission.
func sameOrigin(r *http.Request) bool {
	if r.Header.Get("Sec-Fetch-Site") == "cross-site" {
		return false
	}
	origin := r.Header.Get("Origin")
	if origin == "" {
		return true
	}
	u, err := url.Parse(origin)
	return err == nil && (u.Scheme == "http" || u.Scheme == "https") && u.Host == r.Host
}
func (s *Server) browserJSON(w http.ResponseWriter, r *http.Request) bool {
	w.Header().Set("Cache-Control", "no-store")
	if !sameOrigin(r) {
		s.writeProblem(w, r, 403, "csrf.invalid", nil, "")
		return false
	}
	if strings.Split(r.Header.Get("Content-Type"), ";")[0] != "application/json" {
		s.writeProblem(w, r, 400, "request.invalid_json", nil, "")
		return false
	}
	return true
}
func (s *Server) sessionJSON(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	sess, ok := s.readSession(r)
	data := map[string]any{"authenticated": ok, "locale": requestedLocale(r), "supported_languages": i18n.SupportedCodes()}
	if ok {
		data["csrf_token"] = sess.CSRF
		data["expires_at"] = sess.Expires
		data["username"] = sess.User.Username
		data["role"] = sess.User.Role
		data["user_id"] = sess.User.ID
	}
	writeData(w, 200, data)
}
func (s *Server) loginJSON(w http.ResponseWriter, r *http.Request) {
	if !s.browserJSON(w, r) {
		return
	}
	var input struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if !s.decodeJSON(w, r, &input, 64<<10) {
		return
	}
	user, err := s.core.Authenticate(r.Context(), input.Username, input.Password, "")
	if err != nil {
		s.recordLogin(r, "", false)
		time.Sleep(150 * time.Millisecond)
		s.writeProblem(w, r, 401, "auth.required", nil, "")
		return
	}
	s.recordLogin(r, user.ID, true)
	sess, ok := s.issueSession(w, r, user)
	if !ok {
		return
	}
	writeData(w, 200, map[string]any{"authenticated": true, "locale": requestedLocale(r), "supported_languages": i18n.SupportedCodes(), "csrf_token": sess.CSRF, "expires_at": sess.Expires, "username": user.Username, "role": user.Role, "user_id": user.ID})
}
func (s *Server) logoutJSON(w http.ResponseWriter, r *http.Request) {
	http.SetCookie(w, &http.Cookie{Name: "nsc_session", Value: "", Path: "/", HttpOnly: true, Secure: s.secureSession(), MaxAge: -1, SameSite: http.SameSiteStrictMode})
	w.WriteHeader(204)
}
func (s *Server) localeJSON(w http.ResponseWriter, r *http.Request) {
	if !s.browserJSON(w, r) {
		return
	}
	if sess, ok := s.readSession(r); ok && !secureEqual(r.Header.Get("X-CSRF-Token"), sess.CSRF) {
		s.writeProblem(w, r, 403, "csrf.invalid", nil, "")
		return
	}
	var input struct {
		Lang string `json:"lang"`
	}
	if !s.decodeJSON(w, r, &input, 16<<10) {
		return
	}
	if !i18n.IsSupportedCode(input.Lang) {
		s.writeProblem(w, r, 400, "request.invalid_form", nil, "lang")
		return
	}
	s.localeCookie(w, input.Lang)
	w.Header().Set("Content-Language", input.Lang)
	writeData(w, 200, map[string]string{"locale": input.Lang})
}
